<script setup>
import { onMounted, ref } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';

const admin=useAuthStore().user?.role==='ADMIN',rows=ref([]),page=ref(1),total=ref(0),search=ref(''),category=ref(''),status=ref('');
const editing=ref(null),form=ref({name:'',category:'',description:'',publicAddress:'',publicContact:'',website:'',status:'DRAFT'});
const loading=ref(true),saving=ref(false),error=ref(''),notice=ref('');
async function load(){loading.value=true;error.value='';try{const result=await api.get('/firms',{params:{page:page.value,search:search.value,category:category.value,status:status.value}});rows.value=result.data.data.rows;total.value=result.data.data.total;}catch(e){error.value=e.response?.data?.message||'Could not load partner firms.';}finally{loading.value=false;}}
function edit(item){editing.value=item.id;form.value={name:item.name,category:item.category,description:item.description,publicAddress:item.publicAddress||'',publicContact:item.publicContact||'',website:item.website||'',status:item.status};}
function clear(){editing.value=null;form.value={name:'',category:'',description:'',publicAddress:'',publicContact:'',website:'',status:'DRAFT'};}
async function save(){if(saving.value)return;saving.value=true;error.value='';try{if(editing.value)await api.patch(`/firms/${editing.value}`,form.value);else await api.post('/firms',form.value);notice.value='Firm saved.';clear();await load();}catch(e){error.value=e.response?.data?.message||'Could not save firm.';}finally{saving.value=false;}}
async function setStatus(item,status){if(saving.value||!window.confirm(`${status==='PUBLISHED'?'Publish':status==='ARCHIVED'?'Archive':'Move to draft'} ${item.name}?`))return;saving.value=true;error.value='';try{await api.patch(`/firms/${item.id}`,{name:item.name,category:item.category,description:item.description,publicAddress:item.publicAddress,publicContact:item.publicContact,website:item.website,status});notice.value=`Firm ${status.toLowerCase()}.`;await load();}catch(e){error.value=e.response?.data?.message||'Could not update firm.';}finally{saving.value=false;}}
async function deleteFirm(item){if(saving.value)return;const confirmation=window.prompt(`Permanently delete ${item.name}? Type DELETE to confirm.`);if(confirmation!=='DELETE')return;const reason=window.prompt('Reason for deletion (saved in the audit log):');if(reason===null)return;if(!reason.trim()){error.value='A deletion reason is required.';return;}saving.value=true;error.value='';try{await api.delete(`/firms/${item.id}`,{data:{reason:reason.trim()}});notice.value=`${item.name} was permanently deleted.`;if(editing.value===item.id)clear();await load();if(page.value>1&&!rows.value.length){page.value--;await load();}}catch(e){error.value=e.response?.data?.message||'Could not delete firm. Archive it instead.';if(e.response?.status===404)await load();}finally{saving.value=false;}}
onMounted(load);
</script>
<template><PortalLayout title="Firms"><div class="dashboard content-page"><div class="page-heading"><div><p class="eyebrow">PARTNER DIRECTORY</p><h2>Firms</h2><p>Published public information about partner firms. Opportunities are not managed here.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p>
  <section class="panel"><form class="toolbar" @submit.prevent="page=1;load()"><label>Search firms<input v-model="search" placeholder="Firm name or category"/></label><label>Category<input v-model="category" placeholder="All categories"/></label><label v-if="admin">Status<select v-model="status"><option value="">All statuses</option><option value="DRAFT">Draft</option><option value="PUBLISHED">Published</option><option value="ARCHIVED">Archived</option></select></label><button class="secondary-button">Search</button></form><p v-if="loading" class="empty">Loading firms…</p><div v-else-if="rows.length" class="item-grid"><article v-for="item in rows" :key="item.id" class="record-card"><div><p class="eyebrow">{{item.category}} <span v-if="admin">· {{item.status}}</span></p><h3>{{item.name}}</h3><p>{{item.description}}</p><p v-if="item.publicAddress">{{item.publicAddress}}</p><p v-if="item.publicContact">{{item.publicContact}}</p><a v-if="item.website" :href="item.website" target="_blank" rel="noopener noreferrer">Visit website</a></div><div v-if="admin" class="inline-actions"><button class="text-button" @click="edit(item)">Edit</button><button v-if="item.status!=='PUBLISHED'" class="text-button" :disabled="saving" @click="setStatus(item,'PUBLISHED')">Publish</button><button v-if="item.status==='PUBLISHED'" class="text-button" :disabled="saving" @click="setStatus(item,'DRAFT')">Unpublish</button><button v-if="item.status!=='ARCHIVED'" class="text-button" :disabled="saving" @click="setStatus(item,'ARCHIVED')">Archive</button><button v-if="item.status==='ARCHIVED'" class="text-button destructive" :disabled="saving" @click="deleteFirm(item)">Delete permanently</button></div></article></div><p v-else class="empty">No published firms match this search.</p><div class="pagination"><button :disabled="page===1" @click="page--;load()">Previous</button><span>Page {{page}} · {{total}} firms</span><button :disabled="page*20>=total" @click="page++;load()">Next</button></div></section>
  <section v-if="admin" class="panel narrow-panel"><h2>{{editing?'Edit firm':'Add firm'}}</h2><form class="stack-form" @submit.prevent="save"><label>Firm name<input v-model="form.name" required maxlength="180"/></label><label>Category<input v-model="form.category" required maxlength="100"/></label><label>Description<textarea v-model="form.description" required maxlength="5000"/></label><label>Approved public address<input v-model="form.publicAddress" maxlength="300"/></label><label>Approved public contact<input v-model="form.publicContact" maxlength="190"/></label><label>Website<input v-model="form.website" type="url" maxlength="500" placeholder="https://example.com"/></label><label>Status<select v-model="form.status"><option value="DRAFT">Draft</option><option value="PUBLISHED">Published</option><option value="ARCHIVED">Archived</option></select></label><div class="inline-actions"><button class="primary" :disabled="saving">{{saving?'Saving…':'Save firm'}}</button><button v-if="editing" type="button" class="secondary-button" @click="clear">Cancel edit</button></div></form></section>
</div></PortalLayout></template>
